// TestInvoicesWithoutLinesAnswer is the incident: an invoice without lines (a free plan's, or any the store holds) made the
// invoice views panic, so the list and get answered 500.
func TestInvoicesWithoutLinesAnswer(t *testing.T) {
	e := apitest.New(t)
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	free := e.CreatePlan(e.Acme, "Free", "USD", "0.00")
	var sub store.Subscription
	e.MustDo(http.StatusCreated, "POST", "/v1/subscriptions", e.Acme.Key, map[string]any{"customer_id": c.ID, "plan_id": free.ID}, &sub)
	type invoice struct {
		store.Invoice
		Total       int64
		Description string `json:"description"`
	}
	var invs struct{ Items []invoice }
	e.MustDo(http.StatusOK, "GET", "/v1/invoices?customer_id="+c.ID, e.Acme.Key, nil, &invs)
	if len(invs.Items) != 1 || invs.Items[0].Status != store.InvoicePaid || invs.Items[0].Total != 0 || !strings.HasPrefix(invs.Items[0].Description, "Free, ") {
		t.Fatalf("free plan invoices = %+v", invs)
	}

	empty, err := e.Store.CreateInvoice(store.Invoice{OrgID: e.Acme.ID, CustomerID: c.ID, Currency: money.USD}, e.Clock.Now())
	if err != nil {
		t.Fatal(err)
	}
	var got invoice
	e.MustDo(http.StatusOK, "GET", "/v1/invoices/"+empty.ID, e.Acme.Key, nil, &got)
	if got.ID != empty.ID || got.Description != "" || got.Total != 0 {
		t.Fatalf("invoice without lines = %+v", got)
	}
	e.MustDo(http.StatusOK, "GET", "/v1/invoices?customer_id="+c.ID, e.Acme.Key, nil, &invs)
	if len(invs.Items) != 2 {
		t.Fatalf("invoices = %+v", invs)
	}
	e.MustDo(http.StatusOK, "POST", "/v1/invoices/"+empty.ID+"/pay", e.Acme.Key, nil, &got)
	if got.Status != store.InvoicePaid {
		t.Fatalf("paid = %+v", got)
	}
	empty2, _ := e.Store.CreateInvoice(store.Invoice{OrgID: e.Acme.ID, CustomerID: c.ID, Currency: money.USD}, e.Clock.Now())
	e.MustDo(http.StatusOK, "POST", "/v1/invoices/"+empty2.ID+"/void", e.Acme.Key, nil, &got)
	if got.Status != store.InvoiceVoid {
		t.Fatalf("voided = %+v", got)
	}
